(5191078, 754474, 102481, '<td valign="top">Great photo!! I rated it low because I am not sure it belongs in this category.</td>', 'Great photo!! I rated it low because I am not sure it belongs in this category.', '2009-01-14 14:45:21.000000', NULL, 1),
(5191083, 755695, 25522, '<td valign="top">Saint Frances of Assis</td>', 'Saint Frances of Assis', '2009-01-14 14:48:31.000000', NULL, 1),
(5191101, 754959, 89468, '<td valign="top">Would like to see more of the sushi and less of the ceiling.</td>', 'Would like to see more of the sushi and less of the ceiling.', '2009-01-14 15:10:29.000000', NULL, 1),
(5191128, 754427, 91282, '<td valign="top">I really love the setup and colors here. I wish more of the picture was clear, though.</td>', 'I really love the setup and colors here. I wish more of the picture was clear, though.', '2009-01-14 15:34:52.000000', NULL, 1),
(5191133, 755846, 91282, '<td valign="top">Might have done a tighter crop here. His expression is so excellent. :)</td>', 'Might have done a tighter crop here. His expression is so excellent. :)', '2009-01-14 15:36:35.000000', NULL, 1),
(5191136, 755579, 67152, '<td valign="top">who cares about the fish and chips....give me the Spitfire!</td>', 'who cares about the fish and chips....give me the Spitfire!', '2009-01-14 15:37:41.000000', NULL, 1),
(5191138, 754502, 91282, '<td valign="top">That mug makes a very cool subject, and the swirl of the steam looks great. I don''t much care for whatever its sitting on though; It detracts from the rest of the picture, IMHO.</td>', 'That mug makes a very cool subject, and the swirl of the steam looks great. I don''t much care for whatever its sitting on though; It detracts from the rest of the picture, IMHO.', '2009-01-14 15:38:11.000000', NULL, 1),
(5191139, 755699, 91282, '<td valign="top">Probably would rather not have the lady bug towel in the shot. The bread looks delicious though!</td>', 'Probably would rather not have the lady bug towel in the shot. The bread looks delicious though!', '2009-01-14 15:38:58.000000', NULL, 1),
(5191141, 755995, 91282, '<td valign="top">This shot is <i>beautiful</i>. I love the colors and the composition. 10<br/> <br/>*Question, is that an onion in the bottom right corner? I didn''t notice it at first, but on second glance its bothering me a little. Not enough to change my vote though. :)</td>', 'This shot is beautiful. I love the colors and the composition. 10 *Question, is that an onion in the bottom right corner? I didn''t notice it at first, but on second glance its bothering me a little. Not enough to change my vote though. :)', '2009-01-14 15:41:01.000000', NULL, 1),
(5191145, 755430, 91282, '<td valign="top">This looks a lot like a painter''s palette. It would have been neat to have thrown a paint brush in there too, to emphasize the "art of cooking". :) Very cool.</td>', 'This looks a lot like a painter''s palette. It would have been neat to have thrown a paint brush in there too, to emphasize the "art of cooking". :) Very cool.', '2009-01-14 15:43:37.000000', NULL, 1),
(5191146, 755390, 91282, '<td valign="top">This is one of my favorites in the challenge. So simple and so effective. Love the steam.</td>', 'This is one of my favorites in the challenge. So simple and so effective. Love the steam.', '2009-01-14 15:44:41.000000', NULL, 1),
(5191147, 754986, 91282, '<td valign="top">Cute idea! It''ll be interesting to see how many people understand what it is.</td>', 'Cute idea! It''ll be interesting to see how many people understand what it is.', '2009-01-14 15:45:44.000000', NULL, 1),
(5191149, 755499, 91282, '<td valign="top">Delicious! This really does look like a cookbook photograph.</td>', 'Delicious! This really does look like a cookbook photograph.', '2009-01-14 15:46:10.000000', NULL, 1),
(5191151, 755867, 91282, '<td valign="top">I like the setup of this, and I love the shape of that wine glass! Its so interesting! I probably would''ve cropped out the shadows of the tree branches on the left; Their a tad distracting, IMHO.</td>', 'I like the setup of this, and I love the shape of that wine glass! Its so interesting! I probably would''ve cropped out the shadows of the tree branches on the left; Their a tad distracting, IMHO.', '2009-01-14 15:47:36.000000', NULL, 1),
(5191156, 755509, 91282, '<td valign="top">This is one of my favorites in the challenge. Very creative and well executed. 10 from me.</td>', 'This is one of my favorites in the challenge. Very creative and well executed. 10 from me.', '2009-01-14 15:48:15.000000', NULL, 1),
(5191159, 755941, 91282, '<td valign="top">Looks delicious, especially with those red red tomatoes! Pity about the blur.</td>', 'Looks delicious, especially with those red red tomatoes! Pity about the blur.', '2009-01-14 15:49:10.000000', NULL, 1),
(5191160, 753916, 91282, '<td valign="top">Oh my, that looks SO good! This challenge is making me extremely hungry..</td>', 'Oh my, that looks SO good! This challenge is making me extremely hungry..', '2009-01-14 15:50:02.000000', NULL, 1),
(5191167, 754929, 91282, '<td valign="top">So it took me a few minutes to figure out what that metal thing was. lol Wish the flame had shown up a little more. I think the setup here is nicely done, and does seem to me like it would be a good cookbook photo.</td>', 'So it took me a few minutes to figure out what that metal thing was. lol Wish the flame had shown up a little more. I think the setup here is nicely done, and does seem to me like it would be a good cookbook photo.', '2009-01-14 15:53:58.000000', NULL, 1),
(5191170, 755919, 91282, '<td valign="top">Very nice, candid looking shot. He does sort of have a touch of sadness/loneliness in his expression, doesn''t he? The guy by his shoulder bugs me a little, but considering the circumstances of the location I think you did pretty darn well.</td>', 'Very nice, candid looking shot. He does sort of have a touch of sadness/loneliness in his expression, doesn''t he? The guy by his shoulder bugs me a little, but considering the circumstances of the location I think you did pretty darn well.', '2009-01-14 15:56:21.000000', NULL, 1),
(5191172, 754704, 91282, '<td valign="top">I think the "Total" label there detracts from the "peasant-ness" of the picture. When I think ''peasant'' I think simple, which everything but that label implies. Everything else here works really well though, IMHO.</td>', 'I think the "Total" label there detracts from the "peasant-ness" of the picture. When I think ''peasant'' I think simple, which everything but that label implies. Everything else here works really well though, IMHO.', '2009-01-14 15:59:10.000000', NULL, 1),
(5191182, 754846, 91282, '<td valign="top">Good subject, though I feel maybe a lighter background would have been a better choice.<br/> <br/>This is probably going to sound a little weird, but I feel like the positioning of the cheesecake looks like its got its back turned to me. I don''t like feeling rejected by cheesecake. :(</td>', 'Good subject, though I feel maybe a lighter background would have been a better choice. This is probably going to sound a little weird, but I feel like the positioning of the cheesecake looks like its got its back turned to me. I don''t like feeling rejected by cheesecake. :(', '2009-01-14 16:02:43.000000', NULL, 1),
(5191190, 755941, 90806, '<td valign="top">Appears that everything moved.</td>', 'Appears that everything moved.', '2009-01-14 16:04:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5191191, 754982, 91282, '<td valign="top">I like this shot, and I really like the title too. That bright color would certainly cheer my morning.</td>', 'I like this shot, and I really like the title too. That bright color would certainly cheer my morning.', '2009-01-14 16:04:52.000000', NULL, 1),
(5191196, 755995, 90806, '<td valign="top">DOF a bit shallow for me, would be nice to have one whole slice in focus.</td>', 'DOF a bit shallow for me, would be nice to have one whole slice in focus.', '2009-01-14 16:05:32.000000', NULL, 1),
(5191199, 754244, 91282, '<td valign="top">I really like the way this guy looks! His expression and body language convey a lot. I also think B&amp;W was an excellent choice. 10 from me.</td>', 'I really like the way this guy looks! His expression and body language convey a lot. I also think B&W was an excellent choice. 10 from me.', '2009-01-14 16:05:58.000000', NULL, 1),
(5191207, 755556, 91282, '<td valign="top">That looks delicious! I think the wood surface everything''s sitting on adds a lot to this picture, too. Gives the picture sort of a warm cafe feeling. Very nice.</td>', 'That looks delicious! I think the wood surface everything''s sitting on adds a lot to this picture, too. Gives the picture sort of a warm cafe feeling. Very nice.', '2009-01-14 16:07:52.000000', NULL, 1),
