(5192710, 755949, 26466, '<td valign="top">The flash reflection on the glass doesn''t help the shot. Better to have used a tripod if possible. Also the background offers tones too similar to the ones of the subjects (except for the label maybe), so I''m not sure if the shot would have worked well even with better lighting conditions.</td>', 'The flash reflection on the glass doesn''t help the shot. Better to have used a tripod if possible. Also the background offers tones too similar to the ones of the subjects (except for the label maybe), so I''m not sure if the shot would have worked well even with better lighting conditions.', '2009-01-15 12:17:44.000000', NULL, 1),
(5192711, 755540, 26466, '<td valign="top">Beautiful! Nice color and composition.</td>', 'Beautiful! Nice color and composition.', '2009-01-15 12:18:12.000000', NULL, 1),
(5192717, 754704, 26466, '<td valign="top">Not bad, although I would have put the yoghurt on a little plate or bowl instead of leaving it in the container and showing the label. It''s just nice how everything else looks home made, so it detracts a bit from the global effect.</td>', 'Not bad, although I would have put the yoghurt on a little plate or bowl instead of leaving it in the container and showing the label. It''s just nice how everything else looks home made, so it detracts a bit from the global effect.', '2009-01-15 12:22:38.000000', NULL, 1),
(5192722, 754835, 26466, '<td valign="top">Not bad composition, but the lighting makes it look a bit dull.</td>', 'Not bad composition, but the lighting makes it look a bit dull.', '2009-01-15 12:23:34.000000', NULL, 1),
(5192723, 755995, 26466, '<td valign="top">Nice</td>', 'Nice', '2009-01-15 12:23:40.000000', NULL, 1),
(5192726, 755035, 26466, '<td valign="top">Nice composition! I want to bite into those tomatoes.</td>', 'Nice composition! I want to bite into those tomatoes.', '2009-01-15 12:24:24.000000', NULL, 1),
(5192734, 754515, 26466, '<td valign="top">Nice.</td>', 'Nice.', '2009-01-15 12:29:10.000000', NULL, 1),
(5192800, 754577, 102024, '<td valign="top">The light feels a bit harsh</td>', 'The light feels a bit harsh', '2009-01-15 13:13:14.000000', NULL, 1),
(5192806, 754161, 102024, '<td valign="top">I guess that''s one way to go at a bowl of... cereal?  lol<br/> <br/>Well composed.</td>', 'I guess that''s one way to go at a bowl of... cereal?  lol Well composed.', '2009-01-15 13:14:43.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5192808, 755560, 102024, '<td valign="top">Title fits picture.  Picture fits challenge!</td>', 'Title fits picture.  Picture fits challenge!', '2009-01-15 13:15:14.000000', NULL, 1),
(5192812, 755585, 102024, '<td valign="top">Looks tasty.  Well composed, I think it fits the challenge well.</td>', 'Looks tasty.  Well composed, I think it fits the challenge well.', '2009-01-15 13:15:57.000000', NULL, 1),
(5192813, 755137, 102024, '<td valign="top">Hmm, white balance doesn''t seem ideal for a food shot.  Could be a bit sharper.</td>', 'Hmm, white balance doesn''t seem ideal for a food shot.  Could be a bit sharper.', '2009-01-15 13:16:30.000000', NULL, 1),
(5192817, 754515, 102024, '<td valign="top">Sort of resembles a fruit burger.  Nice rich colors</td>', 'Sort of resembles a fruit burger.  Nice rich colors', '2009-01-15 13:17:17.000000', NULL, 1),
(5192820, 755390, 102024, '<td valign="top">Fits challenge well.  Good lighting on the steam.</td>', 'Fits challenge well.  Good lighting on the steam.', '2009-01-15 13:17:50.000000', NULL, 1),
(5192823, 755949, 102024, '<td valign="top">Not sure the angle really helps the image.  The reflected light is a tad distracting.</td>', 'Not sure the angle really helps the image.  The reflected light is a tad distracting.', '2009-01-15 13:18:35.000000', NULL, 1),
(5192828, 755205, 102024, '<td valign="top">Image feels a bit plain.  The vegetables are very cramped in the frame and the light seems a bit harsh.  Perhaps if there was simply more vegetables and more drops of moisture on them.  Nice rich colors though.</td>', 'Image feels a bit plain.  The vegetables are very cramped in the frame and the light seems a bit harsh.  Perhaps if there was simply more vegetables and more drops of moisture on them.  Nice rich colors though.', '2009-01-15 13:20:26.000000', NULL, 1),
(5192834, 755737, 102024, '<td valign="top">Good job capturing the warm, creaminess of the soup.  The spots where its boiling up are a little distracting and detract from the image, in my opinion.</td>', 'Good job capturing the warm, creaminess of the soup.  The spots where its boiling up are a little distracting and detract from the image, in my opinion.', '2009-01-15 13:23:00.000000', NULL, 1),
(5192836, 755854, 102024, '<td valign="top">I think this photo may have benefited from a slightly deeper DOF.</td>', 'I think this photo may have benefited from a slightly deeper DOF.', '2009-01-15 13:24:58.000000', NULL, 1),
(5192837, 754735, 102024, '<td valign="top">I think this fits the challenge.  I like the lighting and the color/texture is excellent.</td>', 'I think this fits the challenge.  I like the lighting and the color/texture is excellent.', '2009-01-15 13:25:43.000000', NULL, 1),
(5192841, 754327, 102024, '<td valign="top">I like this image.  Though I might have preferred for the shadow of the leaves to have been softer and less prominent.</td>', 'I like this image.  Though I might have preferred for the shadow of the leaves to have been softer and less prominent.', '2009-01-15 13:26:39.000000', NULL, 1),
(5192842, 755509, 102024, '<td valign="top">Fits the challenge, imo.  I like the idea.  Though I wonder how it might look if the ripple was originating from farther back towards the herbs...</td>', 'Fits the challenge, imo.  I like the idea.  Though I wonder how it might look if the ripple was originating from farther back towards the herbs...', '2009-01-15 13:27:59.000000', NULL, 1),
(5192847, 755474, 102024, '<td valign="top">Very strong geometric shapes posed in a very bold composition.  The lighting is good.  But something feels missing... can''t put my finger on it...</td>', 'Very strong geometric shapes posed in a very bold composition.  The lighting is good.  But something feels missing... can''t put my finger on it...', '2009-01-15 13:30:29.000000', NULL, 1),
(5192851, 755993, 102024, '<td valign="top">Well captured.</td>', 'Well captured.', '2009-01-15 13:31:58.000000', NULL, 1),
(5192855, 755936, 102024, '<td valign="top">Wonderfully vibrant colors.  Well composed.  Fits challenge excellently.</td>', 'Wonderfully vibrant colors.  Well composed.  Fits challenge excellently.', '2009-01-15 13:33:19.000000', NULL, 1),
(5192861, 755878, 102024, '<td valign="top">I like the idea, well executed.  Though I would have liked to not be able to see the tiny bit of red skin above the zipper.</td>', 'I like the idea, well executed.  Though I would have liked to not be able to see the tiny bit of red skin above the zipper.', '2009-01-15 13:35:03.000000', NULL, 1),
(5192862, 754302, 102024, '<td valign="top">This would make for a good ad.</td>', 'This would make for a good ad.', '2009-01-15 13:35:44.000000', NULL, 1),
(5192866, 755217, 102024, '<td valign="top">I like the lighting on this one.</td>', 'I like the lighting on this one.', '2009-01-15 13:36:32.000000', NULL, 1),
(5192867, 755191, 102024, '<td valign="top">Well set up.  I might have liked to see the chopped parsley (or whatever it is) to be hugging the bottom of the jar.  And the light from the right is a bit distracting.</td>', 'Well set up.  I might have liked to see the chopped parsley (or whatever it is) to be hugging the bottom of the jar.  And the light from the right is a bit distracting.', '2009-01-15 13:38:06.000000', NULL, 1),
