(5192869, 754321, 102024, '<td valign="top">Definitely a stock photo!</td>', 'Definitely a stock photo!', '2009-01-15 13:38:51.000000', NULL, 1),
(5192870, 755947, 102024, '<td valign="top">Too grainy, in my opinion.  And the reflection of light from the fork prongs is a too bright.</td>', 'Too grainy, in my opinion.  And the reflection of light from the fork prongs is a too bright.', '2009-01-15 13:40:01.000000', NULL, 1),
(5192874, 754846, 102024, '<td valign="top">Not too sure about the registration of the subject, but the cheesecake does look quite delicious!</td>', 'Not too sure about the registration of the subject, but the cheesecake does look quite delicious!', '2009-01-15 13:40:39.000000', NULL, 1),
(5192906, 755941, 47470, '<td valign="top">It looks like there might be motion blur on this.  Using a tripod (or something sturdy to put the camera on) would help that.</td>', 'It looks like there might be motion blur on this.  Using a tripod (or something sturdy to put the camera on) would help that.', '2009-01-15 13:56:07.000000', NULL, 1),
(5192909, 754982, 47470, '<td valign="top">The shadow seems kinda distracting.</td>', 'The shadow seems kinda distracting.', '2009-01-15 13:56:49.000000', NULL, 1),
(5192912, 755965, 47470, '<td valign="top">Nice lighting.  Very pretty.</td>', 'Nice lighting.  Very pretty.', '2009-01-15 13:57:36.000000', NULL, 1),
(5192915, 755878, 47470, '<td valign="top">Cool idea!  I might have upped the saturation on the apple a bit.</td>', 'Cool idea!  I might have upped the saturation on the apple a bit.', '2009-01-15 13:58:28.000000', NULL, 1),
(5192949, 755474, 47470, '<td valign="top">The only thing I would have done differently would be to pop the milk bubbles!  The lighting is very nice.</td>', 'The only thing I would have done differently would be to pop the milk bubbles!  The lighting is very nice.', '2009-01-15 14:16:24.000000', NULL, 1),
(5192954, 755560, 47470, '<td valign="top">I wish their heads weren''t cut off.</td>', 'I wish their heads weren''t cut off.', '2009-01-15 14:17:29.000000', NULL, 1),
(5192967, 755585, 47470, '<td valign="top">Nice use of a slight tilt.</td>', 'Nice use of a slight tilt.', '2009-01-15 14:22:30.000000', NULL, 1),
(5192969, 754735, 47470, '<td valign="top">Nice color and texture.</td>', 'Nice color and texture.', '2009-01-15 14:23:05.000000', NULL, 1),
