(5193385, 755941, 20748, '<td valign="top">invest in a tripod. too much camera shake.</td>', 'invest in a tripod. too much camera shake.', '2009-01-15 19:05:45.000000', NULL, 1),
(5193399, 755978, 99063, '<td valign="top">Indeed it is!  Very clear shot, I like it a lot -- though it might be just a bit too red/bright for me.  ''course that''s just me, though!  great image</td>', 'Indeed it is!  Very clear shot, I like it a lot -- though it might be just a bit too red/bright for me.  ''course that''s just me, though!  great image', '2009-01-15 19:14:06.000000', NULL, 1),
