(5193414, 755949, 20748, '<td valign="top">I''m not feeling the angle or the direct lighting.</td>', 'I''m not feeling the angle or the direct lighting.', '2009-01-15 19:18:55.000000', NULL, 1),
(5193416, 753920, 20748, '<td valign="top">Unfocused</td>', 'Unfocused', '2009-01-15 19:19:13.000000', NULL, 1),
