(5193422, 755499, 99063, '<td valign="top">yum yum eat ''em up!</td>', 'yum yum eat ''em up!', '2009-01-15 19:22:50.000000', NULL, 1),
(5193423, 754959, 20748, '<td valign="top">more sushi, less plate</td>', 'more sushi, less plate', '2009-01-15 19:23:46.000000', NULL, 1),
(5193424, 755878, 99063, '<td valign="top">How clever!!!  :D  By far my favorite, due mainly to the creativity of the shot</td>', 'How clever!!!  :D  By far my favorite, due mainly to the creativity of the shot', '2009-01-15 19:23:55.000000', NULL, 1),
