(5193431, 756003, 99063, '<td valign="top">awww!  :)  I like it.  Cute, clever, well-composed, good lighting, good focus</td>', 'awww!  :)  I like it.  Cute, clever, well-composed, good lighting, good focus', '2009-01-15 19:27:58.000000', NULL, 1),
