(5194298, 754835, 102024, '<td valign="top">Composition is rather bland.  It could be "spiced up" with some nice, lush, green herbs</td>', 'Composition is rather bland.  It could be "spiced up" with some nice, lush, green herbs', '2009-01-16 02:58:07.000000', NULL, 1),
(5194299, 754474, 102024, '<td valign="top">Very nice lighting!</td>', 'Very nice lighting!', '2009-01-16 02:58:28.000000', NULL, 1),
