(5194309, 755540, 102024, '<td valign="top">Well lit.  Good choice of background color.  Very stock photo-esque</td>', 'Well lit.  Good choice of background color.  Very stock photo-esque', '2009-01-16 03:03:41.000000', NULL, 1),
