INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5201363, 755978, 98339, '<td valign="top">I like the background of this...makes the apple stand out</td>', 'I like the background of this...makes the apple stand out', '2009-01-18 10:13:06.000000', NULL, 1),
(5201365, 755869, 47852, '<td valign="top">I like the combination of whole and cut apples (and that you didn''t chop that stem in half on the cut apple).  Also a nice variety of colors, and you picked some good apples with no blemishes (did you clone out something on the red apple in the middle?).  The leaves are a nice addition, but they look unnatural.  The color looks a bit off overall, and the red apple in back looks a bit over saturated.  A good photo for stock as far as setup and composition, just needs a little extra (or less in some cases) post processing to really polish it.</td>', 'I like the combination of whole and cut apples (and that you didn''t chop that stem in half on the cut apple).  Also a nice variety of colors, and you picked some good apples with no blemishes (did you clone out something on the red apple in the middle?).  The leaves are a nice addition, but they look unnatural.  The color looks a bit off overall, and the red apple in back looks a bit over saturated.  A good photo for stock as far as setup and composition, just needs a little extra (or less in some cases) post processing to really polish it.', '2009-01-18 10:13:29.000000', NULL, 1),
