(5205232, 755943, 8054, '<td valign="top">I like the bright colors in the photo. I feel that the straws seem to detract more than they add to the overall feel of the photo.</td>', 'I like the bright colors in the photo. I feel that the straws seem to detract more than they add to the overall feel of the photo.', '2009-01-19 20:31:22.000000', NULL, 1),
(5205236, 755919, 8054, '<td valign="top">Make sure that the background of the main subject is free of interesting objects such as his strange growth of a second human head on his shoulder.</td>', 'Make sure that the background of the main subject is free of interesting objects such as his strange growth of a second human head on his shoulder.', '2009-01-19 20:32:40.000000', NULL, 1),
(5205242, 755991, 8054, '<td valign="top">This is a very simple photo showing red peppers and nothing wrong with that. Not sure how many stock photos include a border (most designers would probably add their own if any). Might benefit from a slightly tighter crop. Excellent work though!</td>', 'This is a very simple photo showing red peppers and nothing wrong with that. Not sure how many stock photos include a border (most designers would probably add their own if any). Might benefit from a slightly tighter crop. Excellent work though!', '2009-01-19 20:35:13.000000', NULL, 1),
(5205246, 755695, 8054, '<td valign="top">I like the overall grainy feel to this shot but somehow I don''t really see much food or cooking-related aspects. Seems like it''s more about the cubby-style cabinet than cooking.</td>', 'I like the overall grainy feel to this shot but somehow I don''t really see much food or cooking-related aspects. Seems like it''s more about the cubby-style cabinet than cooking.', '2009-01-19 20:37:27.000000', NULL, 1);
